import React from 'react';
import './App.css';
import Home from './Components/Home';
import Cart from './Components/Cart';
import Payment from './Components/Payment';
import Register from './Components/Register';
import Search from './Components/Search';
import Profile from './Components/Profile';
import About from './Components/About';
import Login from './Components/Login';
import Logout from './Components/Logout';
import History from './Components/History';
import Order from './Components/Order';
import Track from './Components/Track';
import Products from './Components/Products';
import User from './Components/User';
import RecipeReviewCard from './Components/RecipeReviewCard';
import PasskeySignInPage from './Components/PasskeySignInPage';
import ResponsiveAppBar from './Components/ResponsiveAppBar';
import ProductsCard from './Components/ProductsCard';



function App() {
  return (
    <> 


    <center>
      <ResponsiveAppBar />
      <Home /> 


      <Register />
      <Search />
      <Cart />
      <Payment />
      <About />
      <Login />
      <Profile />

      <Track pid="019393" custoname="Venkatesh" exdeldate="02/01/2025" status="IN PROCSS" deliveryperson="ACHYUTH" authority="BLUEDART"/> 
      <Order oid="33299" odate="31/12/2024" ocustname="CHETHAN" oaddress="KAKANI" odeliverydate="02/01/2025" omodeofpayment="CASH ON DELIVERY"  />  

      <Products id="31585" pname="Laptop" pcategory="Electronics" pprice="1lakh" pquantity="1" /> 
      <Logout />
      <History />
      <RecipeReviewCard />
      <PasskeySignInPage />
      <ProductsCard/>




      <User uname="M.B.CHELLARAO" category="Student"/>

      </center>



    </>
  )
}

export default App;
